using System.Reflection;
using System.Runtime.Serialization;
using GPC.Model.Core;
using GPC.Model.Models;
using GPC.Model.Persistence;
using GPC.Model.Results.State;
using GPC.Model.Stages;

namespace UnitTest;

[TestClass]
public class ConstructionStageDomainTest
{
    [TestMethod]
    public void LegacyArchiveAndStageFingerprintsAreUnchanged()
    {
        // Captured before this change with the released Model 5.1.0.0 (94efc9bc), not regenerated by the new implementation.
        using var file = File.OpenRead(Path.Combine(AppContext.BaseDirectory, "Fixtures", "stage-legacy.xml"));
        var model = ModelArchive.Load(file);
        Assert.AreEqual("A62BC637895E2011BB78E9FBFC089A555F4A75B33018C5CE74B5222BB873AE36", Hash(model.Stages[4]));
        Assert.AreEqual("AE15F10F23B9229A7C89F998A3DD0BD99F5180CD612CDA72A6E3D80D1ABE895A", Hash(model.Stages[9]));
        Assert.AreEqual("18D6A898BF6AE5617EBAAE88B95FC2FAD05A281EA3676984B83220A96B04C7E0", model.AnalysisFingerprint());
        Assert.IsNull(model.Stages[4].Definition);
        Assert.AreEqual(true, model.Stages[4].IsCumulative);
        Assert.AreEqual("001(last)", model.Stages[4].SourceStep);
        using var roundtrip = new MemoryStream(); ModelArchive.SaveDocument(model, roundtrip); roundtrip.Position = 0;
        Assert.AreEqual(model.AnalysisFingerprint(), ModelArchive.Load(roundtrip).AnalysisFingerprint());
    }

    [TestMethod]
    public void ScheduleRoundTripsWithoutAliasingOrPermanentAssignments()
    {
        double[] days = { 2, 5 };
        StageGroupChange[] changes = {
            new("Getto", StageGroupKind.Structure, StageGroupAction.Activate, elementAgeDays: 7),
            new("Casseri", StageGroupKind.Structure, StageGroupAction.Deactivate, redistributionRatio: 0.5),
            new("Appoggi", StageGroupKind.Boundary, StageGroupAction.Activate, boundaryPosition: StageBoundaryPosition.Deformed),
            new("Peso", StageGroupKind.Load, StageGroupAction.Activate, StageEventTiming.First),
            new("Peso", StageGroupKind.Load, StageGroupAction.Deactivate, StageEventTiming.Day, 5)
        };
        var stage = new Stage(1, "Getto") { Definition = new StageDefinition(1, 10, days, changes, true, true, false, 0, "STAG/1") };
        days[0] = 99; changes[0] = null!;
        var copy = ModelArchive.CopyValue(stage);
        Assert.AreEqual(Hash(stage), Hash(copy)); Assert.AreNotSame(stage.Definition, copy.Definition);
        Assert.AreEqual(2, copy.Definition.AdditionalOutputDays[0]);
        Assert.AreEqual(7, copy.Definition.GroupChanges[0].ElementAgeDays);
        Assert.AreEqual(0.5, copy.Definition.GroupChanges[1].RedistributionRatio);
        Assert.AreEqual(StageBoundaryPosition.Deformed, copy.Definition.GroupChanges[2].BoundaryPosition);
        Assert.AreEqual(StageEventTiming.First, copy.Definition.GroupChanges[3].Timing);
        Assert.AreEqual(5, copy.Definition.GroupChanges[4].Day);
        var model = new GPC.Model.Models.Model("staged"); model.Stages.Add(stage);
        model.LoadCases.Add(new GPC.Model.LoadCases.LoadCaseBase("Summation"));
        model.LoadCases.Add(new StageResultCase("Summation(CS)", "Summation"));
        using var stream = new MemoryStream(); ModelArchive.SaveDocument(model, stream); stream.Position = 0;
        var loaded = ModelArchive.Load(stream);
        Assert.AreEqual(model.AnalysisFingerprint(), loaded.AnalysisFingerprint());
        Assert.AreEqual(2, loaded.LoadCases.Count);
        Assert.AreEqual("Summation", ((StageResultCase)loaded.LoadCases["Summation(CS)"]).SourceCaseName);
        Assert.AreEqual(0, loaded.NodesElements.Count);
    }

    [TestMethod]
    public void ChangesAffectRevisionAndUnknownCumulativityIsNotInvented()
    {
        var stage = new Stage(1, "Phase"); var before = Hash(stage);
        stage.Definition = new StageDefinition(1, 0);
        Assert.AreNotEqual(before, Hash(stage)); Assert.IsNull(stage.IsCumulative);
        before = Hash(stage); stage.Definition = new StageDefinition(1, 10);
        Assert.AreNotEqual(before, Hash(stage));
        before = Hash(stage); stage.Definition = new StageDefinition(2, 10);
        Assert.AreNotEqual(before, Hash(stage));
        before = Hash(stage); stage.Definition = new StageDefinition(2, 10, groupChanges: new[] {
            new StageGroupChange("Load", StageGroupKind.Load, StageGroupAction.Activate, StageEventTiming.Last) });
        Assert.AreNotEqual(before, Hash(stage));
    }

    [DataTestMethod]
    [DataRow(-1)] [DataRow(double.NaN)] [DataRow(double.PositiveInfinity)]
    public void InvalidDurationIsRejected(double duration)
        => Assert.ThrowsException<ArgumentOutOfRangeException>(() => new StageDefinition(1, duration));

    [TestMethod]
    public void InvalidScheduleIsRejected()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => new StageDefinition(0, 1));
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => new StageDefinition(1, 1, loadSteps: -1));
        Assert.ThrowsException<ArgumentException>(() => new StageDefinition(1, 1, new[] { 2.0 }));
        Assert.ThrowsException<ArgumentException>(() => new StageDefinition(1, 1, new[] { 0.5, 0.5 }));
        Assert.ThrowsException<ArgumentException>(() => new StageDefinition(1, 1, groupChanges: new[] { (StageGroupChange)null! }));
        Assert.ThrowsException<ArgumentException>(() => new StageDefinition(1, 1, groupChanges: new[] {
            new StageGroupChange("L", StageGroupKind.Load, StageGroupAction.Activate, StageEventTiming.Day, 2) }));
    }

    [TestMethod]
    public void InvalidGroupOperationsAreRejected()
    {
        Assert.ThrowsException<ArgumentException>(() => new StageGroupChange(" ", StageGroupKind.Structure, StageGroupAction.Activate));
        Assert.ThrowsException<ArgumentException>(() => new StageGroupChange("G", (StageGroupKind)99, StageGroupAction.Activate));
        Assert.ThrowsException<ArgumentException>(() => new StageGroupChange("G", StageGroupKind.Load, StageGroupAction.Activate, StageEventTiming.Day));
        Assert.ThrowsException<ArgumentException>(() => new StageGroupChange("G", StageGroupKind.Load, StageGroupAction.Activate, day: 2));
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => new StageGroupChange("G", StageGroupKind.Load, StageGroupAction.Activate, StageEventTiming.Day, -1));
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => new StageGroupChange("G", StageGroupKind.Structure, StageGroupAction.Activate, elementAgeDays: -1));
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => new StageGroupChange("G", StageGroupKind.Structure, StageGroupAction.Deactivate, redistributionRatio: 1.01));
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => new StageGroupChange("G", StageGroupKind.Load, StageGroupAction.Activate, elementAgeDays: 2));
        Assert.ThrowsException<ArgumentException>(() => new StageGroupChange("G", StageGroupKind.Structure, StageGroupAction.Activate, boundaryPosition: StageBoundaryPosition.Original));
        Assert.ThrowsException<ArgumentException>(() => new StageResultCase("CS", " "));
    }

    [TestMethod]
    public void NewerStageSchemasAreRefused()
    {
        foreach (var item in new (ISerializable Value, string Entry)[] {
            (new Stage(1, "S"), "StageVersion"), (new StageDefinition(1, 0), "StageDefinitionVersion"),
            (new StageGroupChange("G", StageGroupKind.Structure, StageGroupAction.Activate), "StageGroupChangeVersion"),
            (new StageResultCase("Summation(CS)", "Summation"), "StageResultCaseVersion") })
        {
            var type = item.Value.GetType(); var info = new SerializationInfo(type, new FormatterConverter());
            item.Value.GetObjectData(info, new StreamingContext());
            var newer = new SerializationInfo(type, new FormatterConverter());
            foreach (SerializationEntry entry in info) newer.AddValue(entry.Name, entry.Name == item.Entry ? 2 : entry.Value, entry.ObjectType);
            var constructor = type.GetConstructor(BindingFlags.Instance | BindingFlags.NonPublic, null, new[] { typeof(SerializationInfo), typeof(StreamingContext) }, null)!;
            var error = Assert.ThrowsException<TargetInvocationException>(() => constructor.Invoke(new object[] { newer, new StreamingContext() }));
            Assert.IsInstanceOfType(error.InnerException, typeof(SerializationException));
            StringAssert.Contains(error.InnerException!.Message, "NewerSerializationVersion");
        }
    }

    [TestMethod]
    public void DisplacementReferencesSurviveCopiesWithoutChangingTheOtherStateFields()
    {
        var state = new ResultState { Phase = "CS1", Step = "001(last)", SourceDisplacementReference = "Current", IsCumulative = null };
        var copy = ModelArchive.CopyValue(state);
        Assert.AreEqual("Current", copy.SourceDisplacementReference); Assert.AreEqual("CS1", copy.Phase); Assert.IsNull(copy.IsCumulative);
        Assert.AreEqual(Hash(state), Hash(copy)); Assert.AreEqual("Current", state.Copy().SourceDisplacementReference);
        copy.SourceDisplacementReference = "Real"; Assert.AreNotEqual(Hash(state), Hash(copy));
    }
    private static string Hash(object value) => ModelValues.Fingerprint(new[] { value });
}
